style.css:
@-moz-document domain("userstyles.org") {
/* Sembunyikan Iklan & Elemen Pengganggu */
  iframe, 
  [id*="google_ads"], 
  [class*="insertion"], 
  [class*="ad-container"],
  [class*="styles-grid_gridTitleName"],
  [class*="category-description"] {
    display: none !important;
  }

  /* Header Minimalis */
  header button:not([class*="search"]), 
  [class*="GoPro"], 
  [class*="CreateStyle"] {
    display: none !important;
  }

  /* Navigasi Kategori Lebih Rapi */
  [class*="categories-list"] img {
    display: none !important;
  }
  [class*="categories-list"] a {
    padding: 6px 12px !important;
    font-size: 13px !important;
    border-radius: 20px !important;
  }

  /* Grid & Kartu Minimalis */
  [class*="styles-grid_cardAuthor"], 
  [class*="styles-grid_cardRating"], 
  [class*="styles-grid_cardStats"] {
    display: none !important;
  }
  
  [class*="styles-grid_cardContainer"] {
    border: none !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.2) !important;
    background: #1a1a1a !important;
    transition: transform 0.2s;
  }

  [class*="styles-grid_cardContainer"]:hover {
    transform: translateY(-5px);
  }

  /* Footer Minimalis (Hanya muncul saat di-hover) */
  footer, [class*="contentinfo"] {
    opacity: 0.1;
    transition: opacity 0.5s;
  }
  footer:hover, [class*="contentinfo"]:hover {
    opacity: 1;
  }
}
